INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Lernfeld 1 > Einrichtung IT-Arbeitsplätze > Systemlieferung, Installation & Übergabe
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Kann die Systemlieferung ohne Rücksicht auf die Lieferfristen erfolgen?', 2, '[{"text": "Nein", "correct": true, "because": "Fristen beeinflussen Planung"}, {"text": "Ja", "correct": false, "because": "Zeitplan ist entscheidend"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen bei der Installation eines IT-Arbeitsplatzes immer alle Komponenten vor Ort überprüft werden?', 2, '[{"text": "Ja", "correct": true, "because": "Sichert Funktion und Vollständigkeit"}, {"text": "Nein", "correct": false, "because": "Überprüfung ist Standard"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Übergabe eines IT-Arbeitsplatzes ohne Benutzerunterweisung möglich?', 2, '[{"text": "Ja", "correct": true, "because": "Technisch möglich, aber nicht optimal"}, {"text": "No", "correct": false, "because": "Unterweisung empfohlen"}]'),
('00000000-0000-0000-0000-000000000000', 'Können IT-Arbeitsplätze ohne Netzwerkkonfiguration in Betrieb genommen werden?', 2, '[{"text": "Ja", "correct": true, "because": "Lokale Nutzung möglich"}, {"text": "Nein", "correct": false, "because": "Netzwerk oft nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Dokumentation bei der Systemlieferung und Installation eines IT-Arbeitsplatzes zwingend erforderlich?', 2, '[{"text": "Nein", "correct": true, "because": "Empfohlen, aber nicht zwingend"}, {"text": "Ja", "correct": false, "because": "Best Practice, nicht Pflicht"}]'),
-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welcher Schritt ist bei der Systemlieferung eines IT-Arbeitsplatzes am wichtigsten?', 3, '[{"text": "Lieferkontrolle", "correct": true, "because": "Sichert Vollständigkeit"}, {"text": "Verpackungsdesign", "correct": false, "because": "Ästhetisch"}, {"text": "Markenwahl", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool wird oft zur Installation eines IT-Arbeitsplatzes verwendet?', 2, '[{"text": "Installationsmedium", "correct": true, "because": "Ermöglicht Software-Setup"}, {"text": "Texteditor", "correct": false, "because": "Nicht relevant"}, {"text": "Browser", "correct": false, "because": "Nachgelagert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponente wird bei der Übergabe eines IT-Arbeitsplatzes typischerweise übergeben?', 2, '[{"text": "Benutzerhandbuch", "correct": true, "because": "Unterstützt Nutzung"}, {"text": "Verpackungsmaterial", "correct": false, "because": "Irrelevant"}, {"text": "Liefervertrag", "correct": false, "because": "Administrativ"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Aspekt ist bei der Installation eines IT-Arbeitsplatzes entscheidend?', 3, '[{"text": "Hardwarekompatibilität", "correct": true, "because": "Sichert Funktion"}, {"text": "Farbauswahl", "correct": false, "because": "Ästhetisch"}, {"text": "Lieferdatum", "correct": false, "because": "Logistisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Hauptziel der Übergabe eines IT-Arbeitsplatzes?', 2, '[{"text": "Nutzerzufriedenheit", "correct": true, "because": "Sichert Akzeptanz"}, {"text": "Minimale Kosten", "correct": false, "because": "Sekundär"}, {"text": "Schnelle Lieferung", "correct": false, "because": "Logistisch"}]'),
-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Schritte gehören zur Systemlieferung eines IT-Arbeitsplatzes?', 4, '[{"text": "Bestellung prüfen", "correct": true, "because": "Sichert Vollständigkeit"}, {"text": "Transport planen", "correct": true, "because": "Logistischer Schritt"}, {"text": "Lieferung kontrollieren", "correct": true, "because": "Überprüft Zustand"}, {"text": "Software entwickeln", "correct": false, "because": "Anderer Prozess"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten werden bei der Installation eines IT-Arbeitsplatzes eingerichtet?', 3, '[{"text": "Hardware", "correct": true, "because": "Physische Basis"}, {"text": "Betriebssystem", "correct": true, "because": "Softwaregrundlage"}, {"text": "Peripheriegeräte", "correct": true, "because": "Für Nutzung nötig"}, {"text": "Lieferpapiere", "correct": false, "because": "Administrativ"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme können bei der Systemlieferung und Installation auftreten?', 3, '[{"text": "Lieferverzögerungen", "correct": true, "because": "Verzögern Planung"}, {"text": "Fehlende Komponenten", "correct": true, "because": "Beeinträchtigen Installation"}, {"text": "Inkompatibilität", "correct": true, "because": "Stört Funktion"}, {"text": "Falsche Farbe", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente sind bei der Übergabe eines IT-Arbeitsplatzes wichtig?', 4, '[{"text": "Benutzerunterweisung", "correct": true, "because": "Sichert Nutzung"}, {"text": "Dokumentation", "correct": true, "because": "Nachvollziehbarkeit"}, {"text": "Funktionstest", "correct": true, "because": "Bestätigt Betrieb"}, {"text": "Transportverpackung", "correct": false, "because": "Nicht mehr nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine gute Systemlieferung und Installation?', 3, '[{"text": "Zeitersparnis", "correct": true, "because": "Effizienter Prozess"}, {"text": "Hohe Zuverlässigkeit", "correct": true, "because": "Funktion gesichert"}, {"text": "Nutzerakzeptanz", "correct": true, "because": "Zufriedenheit steigt"}, {"text": "Geringere Lieferkosten", "correct": false, "because": "Nicht primär"}]'),
-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Die Lieferkontrolle ist bei der Systemlieferung wichtig. b) Installation kann ohne Hardwareprüfung erfolgen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kontrolle ja, Prüfung nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Benutzerunterweisung verbessert die Übergabe. b) Netzwerkkonfiguration ist immer zwingend erforderlich.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Unterweisung ja, Netzwerk optional"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Dokumentation erleichtert die Nachverfolgung. b) Lieferfristen sind bei der Planung unwichtig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Dokumentation ja, Fristen relevant"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Hardwarekompatibilität ist bei der Installation entscheidend. b) Übergabe erfordert keinen Funktionstest.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kompatibilität ja, Test nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Systemlieferung umfasst die Kontrolle der Komponenten. b) Installation ist ohne Betriebssystem möglich.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kontrolle ja, OS nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

